#!/usr/bin/env python3
import json
import os
import sys


def main():
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        sys.exit(1)

    target_dir = sys.argv[1]
    summary_path = "summary.json"

    if os.path.exists(summary_path):
        print(f"refusing to run: {summary_path} already exists", file=sys.stderr)
        sys.exit(1)

    if not os.path.isdir(target_dir):
        print(f"not a directory: {target_dir}", file=sys.stderr)
        sys.exit(1)

    values = []
    for name in os.listdir(target_dir):
        if not name.endswith(".json"):
            continue
        path = os.path.join(target_dir, name)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r") as f:
                data = json.load(f)
        except (OSError, json.JSONDecodeError):
            continue
        if isinstance(data, dict) and "cost_usd" in data:
            values.append(data["cost_usd"])

    total = sum(values)
    mean = total / len(values) if values else 0

    with open(summary_path, "w") as f:
        json.dump({"total": total, "mean": mean}, f)


if __name__ == "__main__":
    main()
